Here is a simplified description of the RenderMan Radiance Transfer (RTRT) algorithm in pseudocode, including refraction:
```
// Function to simulate a single light path
function simulate_light_path(scene, camera, light, ray, depth)
  // Initialize variables
  hit = false
  material = null
  attenuation = 1.0
  color = 0.0

  // Loop through the light path
  while (depth > 0) {
    // Cast a ray from the current point to the light source
    new_ray = cast_ray(scene, camera, light, ray)

    // Check for intersections
    intersection = scene.get_intersection(new_ray)
    if (intersection) {
      // Get the material of the intersected object
      material = intersection.get_material()

      // Compute the refraction
      if (material.is_refractive()) {
        // Compute the refraction factor
        refract_factor = material.get_refractive_index()
        new_ray = refract(new_ray, refract_factor)
        attenuation *= refract_factor
      }

      // Compute the radiance transfer
      radiance = material.get_radiance()
      color += radiance * attenuation
      attenuation *= radiance

      // Continue the light path
      ray = new_ray
      hit = true
    } else {
      // No intersection, end the light path
      break
    }

    // Decrement the depth
    depth -= 1
  }

  return color, hit
end function

// Function to cast a ray from a starting point in a given direction
function cast_ray(scene, camera, light, direction)
  // Compute the starting point of the ray
  start_point = camera.get_position() + direction * camera.get_distance()

  // Check for intersections
  intersection = scene.get_intersection(start_point, direction)
  return intersection.get_ray()

end function

// Function to refract a ray through a medium with a given refractive index
function refract(ray, refractive_index)
  // Compute the refracted direction
  refracted_direction = refract_direction(ray, refractive_index)

  // Create a new ray with the refracted direction
  new_ray = Ray(start_point, refracted_direction)

  return new_ray

end function

// Function to compute the refracted direction
function refract_direction(ray, refractive_index)
  // Compute the incident angle
  incident_angle = angular_difference(ray.direction, refractive_index * ray.direction)

  // Compute the refracted angle
  refracted_angle = refract_angle(incident_angle, refractive_index)

  // Compute the refracted direction
  refracted_direction = ray.direction + refracted_angle

  return refracted_direction

end function

// Function to compute the radiance transfer
function radiance_transfer(scene, camera, light, ray)
  // Compute the radiance
  radiance = light.get_radiance()

  // Compute the attenuation
  attenuation = exp(-ray.length() * light.get_attenuation())

  // Compute the color
  color = radiance * attenuation

  return color

end function
```
